@pytest.mark.parametrize("bad_k", [0, -1, True, False, 2.0, "3", None])
def test_invalid_k_raises_before_consuming_records(bad_k) -> None:
    with pytest.raises(ValueError):
        build_kmer_index(_fail_if_consumed(), bad_k)


